{"sql": "WITH q2 AS (
  SELECT order_id FROM orders
  WHERE order_purchase_timestamp >= '2018-04-01' AND order_purchase_timestamp < '2018-07-01'
), rev AS (
  SELECT r.order_id, count(*) AS n FROM order_reviews r JOIN q2 ON q2.order_id = r.order_id GROUP BY r.order_id
)
SELECT
  round(100.0 * (SELECT count(*) FROM rev) / (SELECT count(*) FROM q2), 2) AS reviewed_rate_pct,
  round(100.0 * (SELECT coalesce(sum(n),0) FROM rev) / (SELECT count(*) FROM q2), 2) AS rows_over_orders_pct,
  round(100.0 * ((SELECT coalesce(sum(n),0) FROM rev) - (SELECT count(*) FROM rev)) / (SELECT count(*) FROM rev), 2) AS overstatement_pct"}
